document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".filter-chip"),t=document.querySelectorAll(".badge-card[data-category]");document.querySelectorAll(".progress-fill").forEach(e=>{const t=e.dataset.progress||"0%";e.style.width="0%",requestAnimationFrame(()=>{setTimeout(()=>{e.style.width=t},120)})}),e.forEach(o=>{o.addEventListener("click",()=>{const r=o.dataset.filter;e.forEach(e=>{const t=e===o;e.classList.toggle("active",t),e.setAttribute("aria-pressed",String(t))}),t.forEach(e=>{const t="all"===r||e.dataset.category===r;e.hidden=!t})})}),t.forEach(e=>{e.addEventListener("click",()=>{const t=e.querySelector(".badge-title")?.textContent?.trim();"function"==typeof showToast&&t&&showToast(`Badge : ${t}`,"info")}),e.addEventListener("keydown",t=>{"Enter"!==t.key&&" "!==t.key||(t.preventDefault(),e.click())})})});